-- Original Sadeem menu import; no billing, offers, loyalty or customer mutations
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE sadeem_before ON COMMIT DROP AS SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) snapshot;
DO $identity$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id='28fe7547-ab2a-47b6-ac62-36121fbb1bae' AND slug='brand-3f7b257437a6' AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Sadeem brand identity changed';END IF;END $identity$;
CREATE TEMP TABLE sadeem_expected_categories ON COMMIT DROP AS SELECT * FROM public.menu_categories WITH NO DATA;
INSERT INTO sadeem_expected_categories(id,cafe_id,branch_id,name,description,sort_order,visible) VALUES('6d89cff0-36c8-4686-8f32-777336e0136e','28fe7547-ab2a-47b6-ac62-36121fbb1bae',NULL,'المشروبات',NULL,0,true);
