INSERT INTO sadeem_expected_categories(id,cafe_id,branch_id,name,description,sort_order,visible) VALUES('d8347c08-02fe-4862-8b63-25c734285388','28fe7547-ab2a-47b6-ac62-36121fbb1bae',NULL,'الحلويات',NULL,3,true);
DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_categories WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae') AND (EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae' EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM sadeem_expected_categories) OR EXISTS(SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM sadeem_expected_categories EXCEPT SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM public.menu_categories WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae')) THEN RAISE EXCEPTION 'Existing categories differ; preserve owner changes';END IF;END $catalog$;
INSERT INTO public.menu_categories(id,cafe_id,branch_id,name,description,sort_order,visible) SELECT id,cafe_id,branch_id,name,description,sort_order,visible FROM sadeem_expected_categories ON CONFLICT(id) DO NOTHING;
CREATE TEMP TABLE sadeem_expected_products ON COMMIT DROP AS SELECT * FROM public.menu_products WITH NO DATA;
