DO $catalog$ BEGIN IF EXISTS(SELECT 1 FROM public.menu_products WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae') AND (EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae' EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM sadeem_expected_products) OR EXISTS(SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM sadeem_expected_products EXCEPT SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM public.menu_products WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae')) THEN RAISE EXCEPTION 'Existing products differ; preserve owner changes';END IF;END $catalog$;
INSERT INTO public.menu_products(id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details) SELECT id,cafe_id,branch_id,category_id,name,description,price,price_options,calories,sort_order,available,catalog_kind,image_storage_path,gallery_storage_paths,commerce_details FROM sadeem_expected_products ON CONFLICT(id) DO NOTHING;
DO $logo$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae') THEN RAISE EXCEPTION 'Sadeem settings missing';END IF;IF EXISTS(SELECT 1 FROM public.cafe_settings WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae' AND ((logo_storage_path IS NOT NULL AND logo_storage_path IS DISTINCT FROM '28fe7547-ab2a-47b6-ac62-36121fbb1bae/identity/sadeem-20261102-eb83656112ec35e6.webp') OR logo_url IS NOT NULL)) OR EXISTS(SELECT 1 FROM public.cafe_custom_identity WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae' AND (logo_storage_path IS DISTINCT FROM '28fe7547-ab2a-47b6-ac62-36121fbb1bae/identity/sadeem-20261102-eb83656112ec35e6.webp' OR logo_url IS NOT NULL OR palette IS DISTINCT FROM '{"primary":"#392014","secondary":"#FFF7EA","accent":"#C85922","background":"#FFF7EA","text":"#FFF7EA"}'::jsonb)) THEN RAISE EXCEPTION 'Existing Sadeem identity differs; preserve owner changes';END IF;END $logo$;
UPDATE public.cafe_settings SET logo_storage_path='28fe7547-ab2a-47b6-ac62-36121fbb1bae/identity/sadeem-20261102-eb83656112ec35e6.webp',updated_at=now() WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae' AND logo_storage_path IS DISTINCT FROM '28fe7547-ab2a-47b6-ac62-36121fbb1bae/identity/sadeem-20261102-eb83656112ec35e6.webp';
INSERT INTO public.cafe_custom_identity(cafe_id,logo_storage_path,logo_url,palette) VALUES('28fe7547-ab2a-47b6-ac62-36121fbb1bae','28fe7547-ab2a-47b6-ac62-36121fbb1bae/identity/sadeem-20261102-eb83656112ec35e6.webp',NULL,'{"primary":"#392014","secondary":"#FFF7EA","accent":"#C85922","background":"#FFF7EA","text":"#FFF7EA"}'::jsonb) ON CONFLICT(cafe_id) DO NOTHING;
DO $verify$ DECLARE actual jsonb;BEGIN SELECT jsonb_build_object('subscriptions',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.subscriptions t ),'loyalty_cards',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.loyalty_cards t ),'cafe_loyalty_programs',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_programs t ),'cafe_loyalty_experience',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_loyalty_experience t ),'offers',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.offers t ),'cafes',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.cafes t ),'menu_products',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_products t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'menu_categories',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.menu_categories t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'cafe_custom_identity',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_custom_identity t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'cafe_settings',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY cafe_id)::text,'')) FROM public.cafe_settings t WHERE cafe_id<>'28fe7547-ab2a-47b6-ac62-36121fbb1bae'),'brand_feature_overrides',(SELECT md5(coalesce(jsonb_agg(to_jsonb(t) ORDER BY id)::text,'')) FROM public.brand_feature_overrides t )) INTO actual;IF actual IS DISTINCT FROM(SELECT snapshot FROM sadeem_before) THEN RAISE EXCEPTION 'Protected brands, loyalty, billing or customer data changed';END IF;IF(SELECT count(*) FROM public.menu_products WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae' AND available AND price>0 AND image_storage_path IS NOT NULL)<>27 OR(SELECT count(*) FROM public.menu_categories WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae')<>4 OR(SELECT sum(jsonb_array_length(commerce_details->'options')) FROM public.menu_products WHERE cafe_id='28fe7547-ab2a-47b6-ac62-36121fbb1bae')<>52 THEN RAISE EXCEPTION 'Sadeem count, prices or media mismatch';END IF;END $verify$;
COMMIT;
